// Assembles the plugin: dist/parley/{main.js, manifest.json, styles.css} and dist/parley-<version>.zip
const fs = require('fs');
const path = require('path');
const JSZip = require('jszip');
const r = (p) => fs.readFileSync(path.join(__dirname, p), 'utf8');
const mod = (code) => `(function(){var module={exports:{}};var exports=module.exports;\n${code}\n;return module.exports;})()`;
const manifest = JSON.parse(r('manifest.json'));

const main = `'use strict';
/* Parley ${manifest.version} — ${manifest.author} — generated by build.js, do not edit */
var obsidian = require('obsidian');
var fs = require('fs');
var path = require('path');
var P = ${mod(r('src/parsers.js'))};
var ZipReader = ${mod(r('src/zipreader.js'))};
var Reader = ${mod(r('src/reader.js'))};
${r('src/main.js')}
module.exports = ParleyPlugin;
`;

const out = path.join(__dirname, 'dist/parley');
fs.rmSync(out, { recursive: true, force: true });
fs.mkdirSync(out, { recursive: true });
const files = { 'main.js': main, 'manifest.json': r('manifest.json'), 'styles.css': r('styles.css') };
const zip = new JSZip();
for (const [n, c] of Object.entries(files)) { fs.writeFileSync(path.join(out, n), c); zip.file('parley/' + n, c); }
zip.generateAsync({ type: 'nodebuffer', compression: 'DEFLATE' }).then((buf) => {
  const zp = path.join(__dirname, `dist/parley-${manifest.version}.zip`);
  fs.writeFileSync(zp, buf);
  console.log('parley', manifest.version + ':', (main.length / 1024).toFixed(0) + ' KB main.js,', path.basename(zp));
});
